<?php
declare(strict_types=1);
require_once __DIR__.'/../config/config.php';require_once __DIR__.'/../config/database.php';require_once __DIR__.'/includes/auth.php';$db=db();
$stats=$db->query("SELECT COUNT(*) total, SUM(status='new') new_count, SUM(status='contacted') contacted_count, SUM(status='proposal') proposal_count, SUM(status='won') won_count, SUM(status='lost') lost_count, SUM(priority='high') high_count, COALESCE(SUM(CASE WHEN status IN ('new','contacted','proposal') THEN estimated_value ELSE 0 END),0) pipeline_value, COALESCE(SUM(CASE WHEN status='won' THEN estimated_value ELSE 0 END),0) won_value, SUM(follow_up_at IS NOT NULL AND follow_up_at <= NOW() AND status NOT IN ('won','lost')) overdue_count, SUM(follow_up_at IS NOT NULL AND DATE(follow_up_at)=CURDATE() AND status NOT IN ('won','lost')) today_count FROM leads")->fetch();$total=(int)$stats['total'];$won=(int)$stats['won_count'];$conversion=$total>0?round(($won/$total)*100,1):0;
$services=$db->query("SELECT COALESCE(NULLIF(service,''),'Unspecified') label,COUNT(*) total,COALESCE(SUM(CASE WHEN status='won' THEN estimated_value ELSE 0 END),0) revenue FROM leads GROUP BY service ORDER BY total DESC LIMIT 8")->fetchAll();$sources=$db->query("SELECT COALESCE(NULLIF(source,''),'Unknown') label,COUNT(*) total FROM leads GROUP BY source ORDER BY total DESC LIMIT 8")->fetchAll();$up=$db->query("SELECT id,name,email,service,status,priority,follow_up_at,estimated_value FROM leads WHERE follow_up_at IS NOT NULL AND status NOT IN ('won','lost') ORDER BY follow_up_at ASC LIMIT 10")->fetchAll();$recent=$db->query("SELECT l.id,l.name,l.service,l.status,l.priority,l.created_at,a.activity_type,a.subject,a.created_at activity_at FROM leads l LEFT JOIN lead_activities a ON a.id=(SELECT id FROM lead_activities WHERE lead_id=l.id ORDER BY created_at DESC,id DESC LIMIT 1) ORDER BY l.created_at DESC LIMIT 10")->fetchAll();$esc=static fn($v):string=>htmlspecialchars((string)($v??''),ENT_QUOTES,'UTF-8');$money=static fn($v):string=>number_format((float)($v??0),2);$dt=static fn($v):string=>$v?date('d M Y, H:i',strtotime((string)$v)):'—';?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>CRM Dashboard | <?=defined('APP_NAME')?$esc(APP_NAME):'Distinguished Web Services'?></title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><style>.metric{border:0;border-radius:18px}.metric .value{font-size:2rem;font-weight:700}.table-card{border:0;border-radius:18px}.bar{height:9px;border-radius:20px;background:#212529}.mini{font-size:.8rem}</style></head><body class="bg-light"><main class="container-fluid px-4 px-xl-5 py-4"><div class="d-flex justify-content-between align-items-center mb-4"><div><h1 class="h2 mb-1">Sales & CRM Dashboard</h1><p class="text-muted mb-0">Lead pipeline, follow-ups and revenue overview</p></div><div class="d-flex gap-2"><a href="leads.php" class="btn btn-dark">Manage Leads</a><a href="index.php" class="btn btn-outline-secondary">Admin</a></div></div><div class="row g-3 mb-4"><div class="col-6 col-xl-3"><div class="card metric shadow-sm p-3 h-100"><div class="text-muted">Total Leads</div><div class="value"><?=$total?></div><div class="mini text-muted">All enquiries</div></div></div><div class="col-6 col-xl-3"><div class="card metric shadow-sm p-3 h-100"><div class="text-muted">New Leads</div><div class="value"><?=$stats['new_count']?></div><div class="mini text-muted">Need first contact</div></div></div><div class="col-6 col-xl-3"><div class="card metric shadow-sm p-3 h-100"><div class="text-muted">Pipeline Value</div><div class="value">₦<?=$money($stats['pipeline_value'])?></div><div class="mini text-muted">Open opportunities</div></div></div><div class="col-6 col-xl-3"><div class="card metric shadow-sm p-3 h-100"><div class="text-muted">Won Revenue</div><div class="value">₦<?=$money($stats['won_value'])?></div><div class="mini text-muted">Conversion <?=$conversion?>%</div></div></div></div><div class="row g-3 mb-4"><div class="col-6 col-md-3"><div class="card shadow-sm p-3 border-0"><strong><?=$stats['today_count']?></strong><span class="text-muted">Follow-ups today</span></div></div><div class="col-6 col-md-3"><div class="card shadow-sm p-3 border-0"><strong class="text-danger"><?=$stats['overdue_count']?></strong><span class="text-muted">Overdue follow-ups</span></div></div><div class="col-6 col-md-3"><div class="card shadow-sm p-3 border-0"><strong class="text-warning"><?=$stats['high_count']?></strong><span class="text-muted">High priority</span></div></div><div class="col-6 col-md-3"><div class="card shadow-sm p-3 border-0"><strong><?=$stats['proposal_count']?></strong><span class="text-muted">Proposals open</span></div></div></div><div class="row g-4"><div class="col-xl-7"><div class="card table-card shadow-sm p-4 mb-4"><div class="d-flex justify-content-between"><h2 class="h5">Upcoming Follow-ups</h2><span class="badge text-bg-dark"><?=count($up)?></span></div><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Lead</th><th>Service</th><th>Status</th><th>Follow-up</th><th></th></tr></thead><tbody><?php foreach($up as $r):?><tr><td><strong><?=$esc($r['name'])?></strong><div class="mini text-muted"><?=$esc($r['email'])?></div></td><td><?=$esc($r['service']?:'—')?></td><td><span class="badge text-bg-light border"><?=$esc(ucfirst($r['status']))?></span></td><td class="<?=strtotime($r['follow_up_at'])<=time()?'text-danger fw-bold':''?>"><?=$esc($dt($r['follow_up_at']))?></td><td><a class="btn btn-sm btn-outline-dark" href="lead.php?id=<?=$r['id']?>">Open</a></td></tr><?php endforeach;?><?php if(!$up):?><tr><td colspan="5" class="text-muted">No upcoming follow-ups.</td></tr><?php endif;?></tbody></table></div></div><div class="card table-card shadow-sm p-4"><h2 class="h5">Recent Leads</h2><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Lead</th><th>Service</th><th>Status</th><th>Latest Activity</th><th></th></tr></thead><tbody><?php foreach($recent as $r):?><tr><td><strong><?=$esc($r['name'])?></strong><div class="mini text-muted"><?=$esc($dt($r['created_at']))?></div></td><td><?=$esc($r['service']?:'—')?></td><td><?=$esc(ucfirst($r['status']))?></td><td><?=$r['activity_type']?$esc(ucfirst(str_replace('_',' ',$r['activity_type'])).': '.($r['subject']?:'Activity')):'<span class="text-muted">No activity</span>'?></td><td><a class="btn btn-sm btn-outline-dark" href="lead.php?id=<?=$r['id']?>">Open</a></td></tr><?php endforeach;?></tbody></table></div></div></div><div class="col-xl-5"><div class="card table-card shadow-sm p-4 mb-4"><h2 class="h5">Leads by Service</h2><?php $max=max(1,...array_column($services,'total'));foreach($services as $s):?><div class="mb-3"><div class="d-flex justify-content-between mb-1"><span><?=$esc($s['label'])?></span><strong><?=$s['total']?></strong></div><div class="progress" style="height:9px"><div class="progress-bar bg-dark" style="width:<?=round(((int)$s['total']/$max)*100)?>%"></div></div><div class="mini text-muted mt-1">Won revenue: ₦<?=$money($s['revenue'])?></div></div><?php endforeach;?></div><div class="card table-card shadow-sm p-4"><h2 class="h5">Lead Sources</h2><?php foreach($sources as $s):?><div class="d-flex justify-content-between py-2 border-bottom"><span><?=$esc($s['label'])?></span><strong><?=$s['total']?></strong></div><?php endforeach;?></div></div></div></main></body></html>